steps.tactic:
let f₁ (v : { v : Fin 48 // v ∈ W₁ }) : { v : Fin 48 // v ∈ W₁ } :=
  if h : v.val.val < 12 then ⟨⟨v.val.val + 7, by omega⟩, by revert v h; decide⟩
  else ⟨⟨v.val.val - 7, by omega⟩, by revert v h; decide⟩

let f₂ (v : { v : Fin 48 // v ∈ W₂ }) : { v : Fin 48 // v ∈ W₂ } :=
  if h : v.val.val < 12 then ⟨⟨v.val.val + 12, by omega⟩, by revert v h; decide⟩
  else ⟨⟨v.val.val - 12, by omega⟩, by revert v h; decide⟩

let fQ (v : { v : Fin 48 // v ∈ Q }) : { v : Fin 48 // v ∈ Q } :=
  if h : v.val.val % 2 = 0 then ⟨⟨v.val.val + 1, by omega⟩, by revert v h; decide⟩
  else ⟨⟨v.val.val - 1, by omega⟩, by revert v h; decide⟩
